{"filename":"routes.py","content":"from flask import Blueprint, request, jsonify, abort
from models import get_db

bp = Blueprint('api', __name__)


def row_to_dict(cursor, row):
    """Convert a SQLite row to a dict using cursor description."""
    return {col[0]: row[idx] for idx, col in enumerate(cursor.description)}

# ---------- Workout Endpoints ----------

@bp.route('/workouts', methods=['GET'])
def get_workouts():
    db = get_db()
    cur = db.execute('SELECT id, title, description, duration_minutes, difficulty FROM workout')
    rows = [row_to_dict(cur, row) for row in cur.fetchall()]
    return jsonify({'success': True, 'data': rows}), 200

@bp.route('/workouts', methods=['POST'])
def create_workout():
    data = request.get_json() or {}
    required = ['id', 'title', 'description', 'duration_minutes', 'difficulty']
    if not all(k in data for k in required):
        return jsonify({'success': False, 'error': 'Missing fields'}), 400
    db = get_db()
    try:
        db.execute(
            'INSERT INTO workout (id, title, description, duration_minutes, difficulty) VALUES (?, ?, ?, ?, ?)',
            (data['id'], data['title'], data['description'], data['duration_minutes'], data['difficulty'])
        )
        db.commit()
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500
    return jsonify({'success': True, 'data': {'id': data['id']}}), 201

# The contract lists two ways of addressing a single workout – '/workouts/:id' and '/workouts/<int:item_id>'.
# Both are handled by the same logic.

@bp.route('/workouts/<string:item_id>', methods=['GET'])
def get_workout_by_id(item_id):
    db = get_db()
    cur = db.execute(
        'SELECT id, title, description, duration_minutes, difficulty FROM workout WHERE id = ?',
        (item_id,)
    )
    row = cur.fetchone()
    if row is None:
        return jsonify({'success': False, 'error': 'Workout not found'}), 404
    return jsonify({'success': True, 'data': row_to_dict(cur, row)}), 200

# Alias for the <int:item_id> pattern – Flask will coerce to string automatically if needed.
@bp.route('/workouts/<int:item_id>', methods=['GET'])
def get_workout_by_int_id(item_id):
    return get_workout_by_id(str(item_id))

